const clean=(value,max=500)=>String(value??'').trim().slice(0,max);

// The prompt never contains access keys, contact details, or prospect records.
export function buildAgentPrompt(question,{connected=false,includeBrief=false,brief={}}={}) {
  const message=clean(question,5000);
  if(!message)throw new Error('Write a question first.');
  const rules=['Work only with private businesses, independent professionals and private-sector career opportunities.','Separate supplied facts from assumptions. Do not invent prospects, buying intent, source checks, conversations or results.','Suggest concrete next steps; do not send messages or change my workspace without asking.'];
  if(connected)rules.unshift('Use my connected Pull GTM MCP tools to read my saved workspace only if useful for this question. Respect the tool permissions and show evidence gaps.');
  else rules.unshift('You do not have access to my Pull GTM workspace. Ask for missing context instead of claiming to have read it.');
  const context=includeBrief?Object.entries({workspace:brief.identity,goal:brief.persona,offer:brief.offer,roles:brief.roles,industries:brief.industries,markets:brief.countries}).map(([key,value])=>[key,clean(value,key==='offer'?500:160)]).filter(([,value])=>value).map(([key,value])=>`${key}: ${value}`).join('\n'):'';
  return `I am using Pull GTM. ${message}\n\n${rules.map((rule,i)=>`${i+1}. ${rule}`).join('\n')}${context?`\n\nMy brief (supplied by me, not independently verified):\n${context}`:''}`;
}

export function localGuidance({mode='empty',items=[],reviewed=0,persona='business'}={}) {
  const counts={fit:items.filter(item=>item.status==='fit').length,review:items.filter(item=>item.status==='review').length,excluded:items.filter(item=>item.status==='excluded').length};
  if(mode==='empty'||!items.length)return {...counts,title:'Start with your own list',detail:persona==='career'?'Import opportunities or contacts you gathered lawfully, then define the roles you want.':'Import a list you own, then define the audience that matters to you.',action:'Import a list',target:'import'};
  if(mode==='example')return {...counts,title:'Explore the method',detail:'These records are fictional. Review a sample to see how Pull separates fit from evidence.',action:'Review examples',target:'prospects'};
  if(counts.review)return {...counts,title:'Close the evidence gaps',detail:`${counts.review} ${counts.review===1?'record needs':'records need'} a closer look before you rely on them.`,action:'Review evidence',target:'prospects'};
  if(counts.fit&&!reviewed)return {...counts,title:'Choose who is worth reaching',detail:`${counts.fit} ${counts.fit===1?'record matches':'records match'} your rules. Check the source and approve each one yourself.`,action:'Review matches',target:'prospects'};
  if(reviewed)return {...counts,title:'Make the next message count',detail:`You reviewed ${reviewed} ${reviewed===1?'prospect':'prospects'}. Prepare a specific, editable message based on verified facts.`,action:'Prepare outreach',target:'drafts'};
  return {...counts,title:'Refine the audience',detail:'Your imported records do not yet match the current rules. Review the criteria and source details.',action:'Adjust audience',target:'prospects'};
}

export function renderAgentAIView({cloud,agentState,state,assistantState,items,escape:e,icon}) {
  const active=Boolean(cloud.user&&cloud.verified&&agentState.tokens.some(token=>token.scopes?.includes('chat:relay')));
  const saved=Boolean(cloud.revision>0&&!cloud.dirty);
  const canUseTools=active&&saved;
  const listening=canUseTools&&agentState.tokens.some(token=>token.scopes?.includes('chat:relay')&&token.last_chat_poll_at&&Date.now()-Date.parse(token.last_chat_poll_at)<120000);
  const guide=localGuidance({mode:state.mode,items,reviewed:state.shortlist.length,persona:state.persona});
  const badge=listening?'Your agent is checking for questions':canUseTools?'Start the relay in your agent':'Useful before you connect';
  return `<section class="ai-workspace agent-ai-workspace">
    <div class="ai-main">
      <div class="ai-toolbar"><span class="ai-status ${canUseTools?'ready':''}"><span></span>${e(badge)}</span><div class="ai-toolbar-actions"><button class="link-button" data-action="ai-refresh">Check access</button><button class="link-button" data-view="connect">Manage connection</button></div></div>
      <div class="agent-ai-intro"><span class="ai-greeting">YOUR AI, YOUR TERMS</span><h2>Think with your own AI.</h2><p>Ask here. A running agent with your permission can answer here using its own model. Pull does not pay for or generate those replies.</p></div>
      <div class="agent-ai-snapshot"><div><span>Audience fit</span><strong>${guide.fit}</strong></div><div><span>Needs evidence</span><strong>${guide.review}</strong></div><div><span>Reviewed by you</span><strong>${state.shortlist.length}</strong></div></div>
      <div class="agent-ai-next"><span class="section-kicker">A GOOD NEXT MOVE</span><h3>${e(guide.title)}</h3><p>${e(guide.detail)}</p><button class="link-button" ${guide.target==='import'?'data-action="import"':`data-view="${e(guide.target)}"`}>${e(guide.action)} ${icon('arrow')}</button></div>
      <div class="agent-ai-questions"><span class="section-kicker">START WITH A QUESTION</span>${[['Refine my audience','Help me refine my audience. Ask which customers I serve best and explain what evidence would make the criteria more precise.'],['Find the gaps','Review the evidence gaps in my prospect list. Distinguish verified facts from missing information.'],['Write in my voice','Help me prepare an honest first message in my voice. Ask for my tone and use only facts I have verified.'],['Plan an automation','Help me choose a suitable Pull workflow for this task. Explain what it will do and ask me to approve before it runs.']].map(([label,prompt],i)=>`<button data-ai-prompt="${i}" aria-label="${e(label)}">${e(label)} ${icon('arrow')}</button>`).join('')}</div>
      ${canUseTools?`<div class="agent-ai-relay"><strong>${listening?'Agent activity seen recently':'Start the conversation relay'}</strong><p>${listening?'Your agent has checked for questions in the last two minutes. Replies appear below after it answers.':'Open your connected AI app and ask it to keep checking for Pull questions while this conversation is open. An access key alone does not start an agent.'}</p><button class="button secondary small" data-action="ai-copy-relay">Copy agent startup instruction</button></div><div class="agent-ai-chat" role="log" aria-label="Conversation with your agent">${assistantState.messages.length?assistantState.messages.map(m=>`<article class="agent-ai-turn"><span>You · ${e(new Date(m.created_at).toLocaleTimeString())}</span><p>${e(m.question)}</p>${m.status==='answered'&&m.answer?`<div class="agent-ai-reply"><span>Your agent</span><p>${e(m.answer)}</p></div>`:`<small>${new Date(m.expires_at)<=new Date()?'Question expired without an answer':m.status==='claimed'?'Your agent is working on this':'Waiting for your agent'}</small>`}</article>`).join(''):'<p class="agent-ai-empty">Your conversation will appear here after you send a question. Answers come only from your running agent.</p>'}</div>`:''}
      <form id="ai-form" class="ai-composer agent-ai-composer"><label for="ai-message">What are you working on?</label><textarea id="ai-message" name="message" rows="3" maxlength="5000" placeholder="For example, help me assess whether these car-buyer enquiries show real intent…">${e(assistantState.draft)}</textarea><div class="ai-composer-bottom"><span>${canUseTools?'This question is queued for your running agent; no Pull model is called.':'You can prepare a useful prompt even without MCP.'}</span><button class="button primary" type="submit" ${assistantState.busy?'disabled':''}>${canUseTools?'Ask my agent':'Prepare prompt'} ${icon('arrow')}</button></div></form>
      ${assistantState.error?`<p class="agent-ai-error" role="alert">${e(assistantState.error)}</p>`:''}
      ${!canUseTools&&assistantState.preparedPrompt?`<div class="agent-ai-handoff" role="status"><div><span class="section-kicker">READY FOR YOUR AI APP</span><h3>Paste this into your assistant.</h3><p>Without MCP, your assistant knows only what you include in this prompt. Pull has not sent this question or received a model reply.</p></div><textarea id="ai-prepared-prompt" readonly rows="9" spellcheck="false">${e(assistantState.preparedPrompt)}</textarea><button class="button secondary" data-action="ai-copy-prompt">Copy prompt</button></div>`:''}
    </div>
    <aside class="ai-context agent-ai-aside"><div class="ai-context-head"><span class="section-kicker">YOUR CONTROL</span><h3>Workspace access</h3>${icon('shield')}</div><div class="ai-context-business"><span>${state.context==='company'?'Company workspace':'Personal workspace'}</span><strong>${e(state.identity)}</strong><p>${state.offer?e(state.offer):'Add a clear offer or goal to sharpen your questions.'}</p><button class="link-button" data-action="workspace">Edit your brief</button></div><div class="agent-ai-access"><span class="badge ${canUseTools?'fit':'review'}">${canUseTools?'Relay permission ready':active?'Save needed':'MCP optional'}</span><p>${canUseTools?'An active relay key exists and this workspace is saved. Your agent must be running and checking for questions; a key alone does not prove the app is connected.':active?'Your relay key exists, but save your current workspace to the cloud before using it here.':'You can use local insights and prepare prompts now. Connect Claude Code, Codex, Cursor or another compatible app later.'}</p>${!cloud.user?'<button class="link-button" data-action="account">Sign in</button>':active&&!saved?'<button class="link-button" data-action="account">Save to cloud</button>':'<button class="link-button" data-view="connect">Set up your AI ↗</button>'}</div><label class="ai-context-choice"><input id="ai-share-context" type="checkbox" ${assistantState.shareContext?'checked':''}><span>${canUseTools?'Ask my agent to use Pull tools':'Include my brief in the prompt'}</span></label><p class="ai-context-note">Pull does not add access keys or prospect contact details to a prepared prompt. Review what you write before sharing it with your AI app.</p><div class="ai-principle">${icon('shield')}<p>Evidence first.<br><strong>You decide.</strong><small>Local counts are rule-based. They do not mean a person is ready to buy.</small></p></div></aside>
  </section>`;
}
